// Dibuat otomatis. Pola teks dinamis (berisi angka atau nama) ke bahasa Inggris.

part of 'tr.dart';

final List<_Template> _templates = [
  _Template(RegExp(r'^Minggu (\d+)$'), (m) => 'Week ${_g(m, 1)}'),
  _Template(RegExp(r'^(Selamat (?:pagi|siang|sore|malam)), (.+)$'), (m) => '${_t(m, 1)}, ${_g(m, 2)}'),
  _Template(RegExp(r'^(Hari ini|Kemarin|Minggu ini), (\d{2})\.(\d{2})$'), (m) => '${_t(m, 1)}, ${_g(m, 2)}:${_g(m, 3)}'),
  _Template(RegExp(r'^(\d+) dompet$'), (m) => _g(m, 1) == '1' ? '${_g(m, 1)} wallet' : '${_g(m, 1)} wallets'),
  _Template(RegExp(r'^(\d+) transaksi tercatat$'), (m) => _g(m, 1) == '1' ? '${_g(m, 1)} transaction recorded' : '${_g(m, 1)} transactions recorded'),
  _Template(RegExp(r'^(\d+) transaksi$'), (m) => _g(m, 1) == '1' ? '${_g(m, 1)} transaction' : '${_g(m, 1)} transactions'),
  _Template(RegExp(r'^(\d+) hari$'), (m) => _g(m, 1) == '1' ? '${_g(m, 1)} day' : '${_g(m, 1)} days'),
  _Template(RegExp(r'^(\d+) menit$'), (m) => _g(m, 1) == '1' ? '${_g(m, 1)} minute' : '${_g(m, 1)} minutes'),
  _Template(RegExp(r'^Versi (.+), offline tanpa akun$'), (m) => 'Version ${_g(m, 1)}, offline, no account needed'),
  _Template(RegExp(r'^Versi (.+) sudah terpasang di perangkat ini\.$'), (m) => 'Version ${_g(m, 1)} is already installed on this device.'),
  _Template(RegExp(r'^Versi (.+)$'), (m) => 'Version ${_g(m, 1)}'),
  _Template(RegExp(r'^Ukuran file: (.+)$'), (m) => 'File size: ${_g(m, 1)}'),
  _Template(RegExp(r'^MyWallet v(.+) sudah tersedia\. Unduh pembaruan untuk mendapatkan perbaikan dan peningkatan terbaru\.$'), (m) => 'MyWallet v${_g(m, 1)} is available. Download the update to get the latest fixes and improvements.'),
  _Template(RegExp(r'^PIN aktif, (.+)$'), (m) => 'PIN on, ${_t(m, 1)}'),
  _Template(RegExp(r'^(Rp[^ ]+) dari (Rp[^ ]+)$'), (m) => '${_g(m, 1)} of ${_g(m, 2)}'),
  _Template(RegExp(r'^dari (Rp[^ ]+)$'), (m) => 'of ${_g(m, 1)}'),
  _Template(RegExp(r'^Saldo (Rp.+)$'), (m) => 'Balance ${_g(m, 1)}'),
  _Template(RegExp(r'^Total keluar dari dompet asal: (.+)$'), (m) => 'Total leaving the source wallet: ${_g(m, 1)}'),
  _Template(RegExp(r'^Pengeluaran terbesar: (.+)$'), (m) => 'Biggest expense: ${_t(m, 1)}'),
  _Template(RegExp(r'^Terbesar: (.+)$'), (m) => 'Largest: ${_t(m, 1)}'),
  _Template(RegExp(r'^Budget bulan ini sudah terpakai (\d+)%\.$'), (m) => 'This month\'s budget is ${_g(m, 1)}% used.'),
  _Template(RegExp(r'^Budget kategori sudah terpakai (\d+)%\.$'), (m) => 'Category budget is ${_g(m, 1)}% used.'),
  _Template(RegExp(r'^Halo, (.+)$'), (m) => 'Hello, ${_g(m, 1)}'),
  _Template(RegExp(r'^(.+) tidak aktif$'), (m) => '${_t(m, 1)} is inactive'),
  _Template(RegExp(r'^(.+) akan dihapus jika belum dipakai transaksi\.$'), (m) => '${_g(m, 1)} will be deleted if it has no transactions.'),
  _Template(RegExp(r'^Pemasukan lebih besar (.+) dari pengeluaran\. Kamu menyisihkan (\d+)% dari pemasukan\.$'), (m) => 'Income is ${_g(m, 1)} higher than spending. You saved ${_g(m, 2)}% of your income.'),
  _Template(RegExp(r'^Defisit (.+) bulan ini\. Tinjau kategori terbesar untuk mencari yang bisa dikurangi\.$'), (m) => 'Deficit of ${_g(m, 1)} this month. Review the largest categories to find what can be cut.'),
  _Template(RegExp(r'^(.+) melewati batas yang kamu atur\.$'), (m) => '${_labels(_g(m, 1))} went over the limit you set.'),
  _Template(RegExp(r'^(.+) sudah terpakai lebih dari 80%\.$'), (m) => '${_labels(_g(m, 1))} has used more than 80% of the limit.'),
  _Template(RegExp(r'^Pengeluaran sejauh ini (.+), atau (\d+)% dari total bulan sebelumnya \((.+)\)\.$'), (m) => 'Spending so far is ${_g(m, 1)}, or ${_g(m, 2)}% of last month\'s total (${_g(m, 3)}).'),
  _Template(RegExp(r'^Pengeluaran naik (\d+)%$'), (m) => 'Spending up ${_g(m, 1)}%'),
  _Template(RegExp(r'^Pengeluaran turun (\d+)%$'), (m) => 'Spending down ${_g(m, 1)}%'),
  _Template(RegExp(r'^Hampir sama dengan bulan sebelumnya \((.+)\)\.$'), (m) => 'About the same as last month (${_g(m, 1)}).'),
  _Template(RegExp(r'^Bulan sebelumnya (.+), bulan ini (.+)\.$'), (m) => 'Last month ${_g(m, 1)}, this month ${_g(m, 2)}.'),
  _Template(RegExp(r'^(.+), atau (\d+)% dari total pengeluaran\.$'), (m) => '${_g(m, 1)}, or ${_g(m, 2)}% of total spending.'),
  _Template(RegExp(r'^Rata-rata (.+) per hari\. Hari terboros (.+) \((.+)\)\.$'), (m) => 'Average ${_g(m, 1)} per day. Biggest spending day ${_dates(_g(m, 2))} (${_g(m, 3)}).'),
  _Template(RegExp(r'^(.+) untuk (.+) pada (.+)\.$'), (m) => '${_g(m, 1)} for ${_t(m, 2)} on ${_dates(_g(m, 3))}.'),
  _Template(RegExp(r'^Catat pemasukan atau pengeluaran di (.+) untuk melihat ringkasan dan insight\.$'), (m) => 'Record income or spending in ${_dates(_g(m, 1))} to see the overview and insights.'),
  _Template(RegExp(r'^Ringkasan otomatis dari catatanmu di (.+)\.$'), (m) => 'Automatic summary of your records in ${_dates(_g(m, 1))}.'),
  _Template(RegExp(r'^Tidak ada data di (.+)\.$'), (m) => 'There is no data in ${_dates(_g(m, 1))}.'),
  _Template(RegExp(r'^Tidak ada transaksi pada (.+)\.$'), (m) => 'There are no transactions in ${_dates(_g(m, 1))}.'),
  _Template(RegExp(r'^Masuk (.+) · Keluar (.+)$'), (m) => 'Income ${_g(m, 1)} · Expense ${_g(m, 2)}'),
  _Template(RegExp(r'^(\d+) transaksi · (.+) · (.+)$'), (m) => '${_g(m, 1)} transactions · ${_g(m, 2)} · ${_dates(_g(m, 3))}'),
  _Template(RegExp(r'^Keluar (Rp.+)$'), (m) => 'Spent ${_g(m, 1)}'),
  _Template(RegExp(r'^([\d,\.]+)% dari total • (\d+) transaksi$'), (m) => '${_g(m, 1)}% of total • ${_g(m, 2)} transactions'),
  _Template(RegExp(r'^(-?[\d,\.]+)% dari pemasukan$'), (m) => '${_g(m, 1)}% of income'),
  _Template(RegExp(r'^Sama dengan (.+)$'), (m) => 'Same as ${_t(m, 1)}'),
  _Template(RegExp(r'^([\d,\.]+)% naik dari (.+)$'), (m) => '${_g(m, 1)}% up from ${_t(m, 2)}'),
  _Template(RegExp(r'^([\d,\.]+)% turun dari (.+)$'), (m) => '${_g(m, 1)}% down from ${_t(m, 2)}'),
  _Template(RegExp(r'^Memulihkan cadangan akan mengganti data yang ada di perangkat ini\. Pastikan kamu sudah mencadangkan data terbaru\.\n\nIsi cadangan: (\d+) transaksi, (\d+) dompet, (\d+) kategori, dan (\d+) budget\.$'), (m) => 'Restoring a backup will replace the data on this device. Make sure you have backed up your latest data.\n\nBackup contents: ${_g(m, 1)} transactions, ${_g(m, 2)} wallets, ${_g(m, 3)} categories, and ${_g(m, 4)} budgets.'),
  _Template(RegExp(r'^([\s\S]+)\nData tersimpan lokal di perangkat\. Tidak perlu akun atau koneksi cloud\.$'), (m) => '${_t(m, 1)}\nData is stored locally on your device. No account or cloud connection is needed.'),
];
